/**
 * Brazilian Portuguese dictionary — word lookup with IPA pronunciations.
 * Every word appearing in the Portuguese deck should have an entry.
 */

export interface DictEntry {
  en: string;
  ipa: string;
  pos?: string; // n, v, adj, adv, prep, conj, det, pron
}

