  'do': ['de', 'o'], 'da': ['de', 'a'], 'dos': ['de', 'os'], 'das': ['de', 'as'],
  'no': ['em', 'o'], 'na': ['em', 'a'], 'nos': ['em', 'os'], 'nas': ['em', 'as'],
