  'pelos': ['por', 'os'], 'pelas': ['por', 'as'],
  'num': ['em', 'um'], 'numa': ['em', 'uma'], 'dum': ['de', 'um'], 'duma': ['de', 'uma'],
  'neste': ['em', 'este'], 'nesta': ['em', 'esta'], 'nesse': ['em', 'esse'], 'nessa': ['em', 'essa'],
  'naquele': ['em', 'aquele'], 'naquela': ['em', 'aquela'],
  'deste': ['de', 'este'], 'desta': ['de', 'esta'], 'desse': ['de', 'esse'], 'dessa': ['de', 'essa'],
  'daquele': ['de', 'aquele'], 'daquela': ['de', 'aquela'],
